  "Ahora estás cerrado: no se ve hasta que abras.": "Orain itxita zaude: ez da ikusiko ireki arte.",
  "Ahora estás cerrado: tu ficha no lo enseña.": "Orain itxita zaude: zure fitxak ez du erakusten.",
  "ahora mismo": "oraintxe bertan",
  "Ahora mismo no hay otro plan al que cambiar.": "Une honetan ez dago aldatzeko beste planik.",
