  "Ahora mismo no se puede pausar. Escríbenos a info@klendar.app.": "Oraintxe ezin da pausatu. Idatzi iezaguzu info@klendar.app helbidera.",
  "Ahora mismo no se puede: el plan tiene que estar pagado y al día.": "Oraintxe ezin da: planak ordainduta eta egunean egon behar du.",
  "Ahora mismo no se puede: la suscripción no está activa.": "Une honetan ezin da: harpidetza ez dago aktibo.",
  "Ahora mismo no se ve nada de tu negocio. Lo abres de nuevo cuando quieras.": "Une honetan ez da zure negozioaren ezer ikusten. Nahi duzunean ireki dezakezu berriro.",
  "Ahora mismo no se ve nada de tu negocio. Mañana vuelve a verse solo.": "Une honetan ez da zure negozioaren ezer ikusten. Bihar berriro ikusiko da bere kabuz.",
