  "Ahora no pagas nada, así que no cambia nada: solo que no empezaremos a cobrarte cuando acabe el periodo gratis. Puedes deshacerlo cuando quieras.": "Orain ez duzu ezer ordaintzen; beraz, ez da ezer aldatzen: doako aldia amaitzean ez dizugu kobratzen hasiko, besterik ez. Nahi duzunean desegin dezakezu.",
