  "Al día, con pago por transferencia. Sin permanencia y sin comisión por canje.": "Egunean, transferentzia bidezko ordainketarekin. Iraupen-konpromisorik eta trukeko komisiorik gabe.",
  "Al día. Sin permanencia y sin comisión por canje.": "Egunean. Iraupen-konpromisorik eta trukeko komisiorik gabe.",
  "Al eliminarlo anulamos las reservas y los códigos sin usar y avisamos a cada persona; también a quien tiene sellos, un premio o un regalo, y a tu equipo. Solo guardamos los datos de facturación el tiempo que obliga la ley.": "Ezabatzean, erabili gabeko erreserbak eta kodeak baliogabetu eta pertsona bakoitzari abisatuko diogu; baita zigiluak, saria edo oparia dutenei eta zure taldeari ere. Fakturazio-datuak legeak eskatzen duen denboran bakarrik gordetzen ditugu.",
  "Al llegar a ese número, el QR se cierra solo.": "Kopuru horretara iristean, QRa bakarrik ixten da.",
  "Al menos": "Gutxienez",
  "al mes": "hilean",
  "Al pagar, tu negocio vuelve a funcionar solo. Sin permanencia: cancelas cuando quieras.": "Ordaintzean, zure negozioa berez itzultzen da martxan. Iraunkortasunik gabe: nahi duzunean uzten duzu.",
  "Al propietario no se le cambia el rol desde aquí.": "Jabearen rola ezin da hemendik aldatu.",
  "Al terminar, Klendar sortea solo con un sistema verificable: cualquiera puede comprobar el resultado. Quien gana lo acepta en la app y tú se lo entregas en tu local y lo marcas como entregado.": "Amaitzean, Klendarrek bere kabuz zozketatzen du sistema egiaztagarri batekin: edonork egiazta dezake emaitza. Irabazleak aplikazioan onartzen du, eta zuk zure lokalean ematen diozu eta emanda gisa markatzen duzu.",
