  "Antes de empezar publicamos el resumen de una semilla secreta. Al terminar publicamos la semilla: con ella cualquiera puede repetir el sorteo y ver que sale lo mismo.": "Hasi aurretik, hazi sekretu baten laburpena argitaratzen dugu. Amaitzean, hazia argitaratzen dugu: harekin edonork errepika dezake zozketa, eta emaitza bera ateratzen dela ikusi.",
  "Antes de que estuvieras en Klendar, esta gente pidió que estuvieras con «Pedir un local». No sabemos (ni te decimos) quiénes son: solo cuántos. Ya les hemos avisado de que estás.": "Klendarren egon aurretik, jende honek zu egotea eskatu zuen «Eskatu lokal bat» erabiliz. Ez dakigu (eta ez dizugu esaten) nor diren: zenbat bakarrik. Dagoeneko abisatu diegu hemen zaudela.",
