  "Ayuntamiento, junta de distrito, asociación de comerciantes o vecinal, u ONG. Lo comprobamos antes de poner el sello de entidad en tu ficha y te podemos pedir un documento. De momento, las entidades no pagan cuota.": "Udala, barrutiko batzordea, merkatarien elkartea edo auzo-elkartea, edo GKEa. Zure fitxan erakundearen zigilua jarri aurretik egiaztatu egiten dugu, eta agiri bat eska diezazukegu. Oraingoz, erakundeek ez dute kuotarik ordaintzen.",
