  "Cada año": "Urtero",
  "Cada barra es un día: la altura son las vistas y la parte rellena, los canjes.": "Barra bakoitza egun bat da: altuera bistaratzeak dira, eta betetako zatia, trukeak.",
  "Cada barra son 15 minutos: la altura, cuánta gente había como mucho. La línea discontinua es tu aforo máximo. Solo números: nunca quién.": "Barra bakoitza 15 minutu da: altuera, gehienez zenbat jende zegoen. Marra etena zure gehieneko edukiera da. Zenbakiak bakarrik: inoiz ez nor.",
  "Cada canje genera un código QR de un solo uso. Sube el número si quieres que la misma persona pueda repetir (por ejemplo, un café al día).": "Truke bakoitzak erabilera bakarreko QR kode bat sortzen du. Igo zenbakia pertsona berak errepikatzea nahi baduzu (adibidez, kafe bat egunean).",
  "Cada cuánto": "Zenbatean behin",
  "Cada enlace lleva su QR y sus visitas: uno para Instagram, otro para el grupo de WhatsApp…": "Esteka bakoitzak bere QRa eta bisitak ditu: bat Instagramerako, beste bat WhatsApp taldearentzat…",
  "Cada línea es un código validado en el local, con quién lo validó. Sirve de justificante para el gestor.": "Lerro bakoitza lokalean balidatutako kode bat da, nork balidatu zuen adierazita. Gestoriarentzako egiaztagiri gisa balio du.",
  "Cada mes": "Hilero",
  "Cada RRPP puede apuntar a 1 persona": "RRPP bakoitzak pertsona 1 apunta dezake",
