  "Cada RRPP puede apuntar a {cupo} personas": "RRPP bakoitzak {cupo} pertsona apunta ditzake",
  "cada tarjeta encendida que encaje da su sello": "bat datorren txartel piztu bakoitzak bere zigilua ematen du",
  "Cada tarjeta tiene su meta, su premio y lo que da sello: todas las publicaciones, solo las ofertas flash, solo los eventos, ciertas categorías o ciertas publicaciones. Cuando validas un código,": "Txartel bakoitzak bere helburua, saria eta zigilua zerk ematen duen ditu: argitalpen guztiek, flash eskaintzek bakarrik, ekitaldiek bakarrik, kategoria jakin batzuek edo argitalpen jakin batzuek. Kode bat balidatzen duzunean,",
  "Cada una se publica sola a su hora. Si la de la semana pasada sigue activa, esa semana se salta: no se apilan.": "Bakoitza bere orduan argitaratzen da bere kabuz. Aurreko astekoa oraindik aktibo badago, aste hori saltatu egiten da: ez dira pilatzen.",
