  "Como no tienes local fijo, cada publicación lleva su sitio.": "Lokal finkorik ez duzunez, argitalpen bakoitzak bere lekua du.",
  "Como un cartel: el título enorme y la fecha arriba. Ideal para eventos.": "Kartel bat bezala: izenburua erraldoia eta data goian. Ekitaldietarako ezin hobea.",
