  "Comprobado: sale lo mismo.": "Egiaztatuta: emaitza bera ateratzen da.",
  "Comprobamos que representas a la entidad antes de hacerla pública (normalmente en 24–48 h); hasta entonces no se puede publicar. Hace falta tener 18 años. De momento, las entidades no pagan cuota.": "Erakundea ordezkatzen duzula egiaztatzen dugu publiko egin aurretik (normalean 24–48 h-ko epean); ordura arte ezin da argitaratu. 18 urte izan behar dituzu. Oraingoz, erakundeek ez dute kuotarik ordaintzen.",
  "Comprobando la entidad": "Erakundea egiaztatzen",
  "Comprobando…": "Egiaztatzen…",
  "Comprobar el resultado": "Egiaztatu emaitza",
  "Comprueba que el horario está bien. Si lo está, confírmalo.": "Egiaztatu ordutegia zuzena dela. Hala bada, berretsi.",
  "con carné": "txartelarekin",
  "Con carné de estudiante": "Ikasle-txartelarekin",
