  "con condiciones": "baldintzekin",
  "Con el": "Norbaiten",
  "Con el aforo en directo, lo que marques manda 30 minutos.": "Edukiera zuzenean erabiliz, markatzen duzunak 30 minutu agintzen du.",
  "Con el negocio bloqueado o en pausa puedes descontar usos de los bonos que ya tiene la gente, pero no cargar bonos nuevos.": "Negozioa blokeatuta edo etenda dagoen bitartean, jendeak dituen bonuen erabilerak deskonta ditzakezu, baina ezin duzu bonu berririk kargatu.",
  "Con el negocio parado solo puedes dar lo que ya tenía la gente: sellos y usos de bonos.": "Negozioa geldirik dagoela, jendeak lehendik zuena bakarrik eman dezakezu: zigiluak eta bonuen erabilerak.",
  "Con el negocio parado solo puedes dar usos de bonos que la gente ya tiene: los sellos nuevos y «algo del momento» vuelven cuando se reactive.": "Negozioa geldirik dagoela, jendeak lehendik dituen bonuen erabilerak bakarrik eman ditzakezu: zigilu berriak eta «une honetako zerbait» berriz aktibatzean itzuliko dira.",
  "Con el plan anual, escríbenos y alargamos la renovación.": "Urteko planarekin, idatzi iezaguzu eta berritzea atzeratuko dugu.",
  "Con el precio, la línea y la comida/cena de arriba. No se publica los días cerrados ni si ese día ya has publicado uno. Te avisamos para que añadas la foto.": "Goiko prezioa, lerroa eta bazkaria/afaria erabiliz. Ez da argitaratzen itxitako egunetan, ezta egun horretan bat argitaratu baduzu ere. Abisua bidaliko dizugu argazkia gehi dezazun.",
  "Con enlace a «{offer_title}»": "«{offer_title}» argitalpenerako estekarekin",
  "Con fecha y hora. Puede tener precio y enlace para entradas.": "Data eta ordua ditu. Prezioa eta sarreretarako esteka izan ditzake.",
  "Con fecha, aforo y reserva de plaza": "Datarekin, edukierarekin eta plaza-erreserbarekin",
  "Con la cámara o escribiendo el código": "Kamerarekin edo kodea idatzita",
  "Con la misma cuenta que usas en la app o en la web. Si tu negocio todavía no está dado de alta, entra y lo das de alta aquí mismo.": "Aplikazioan edo webean erabiltzen duzun kontu berarekin. Zure negozioak oraindik alta emanda ez badu, hasi saioa eta eman alta hemen bertan.",
  "con reserva": "erreserbarekin",
  "Con sellos ahora": "Zigiluak dituztenak orain",
