  "Con todo hasta el {fin}. El {due_on} se suma a tu suscripción, sin cortes.": "Dena barne {fin} arte. {due_on}(e)an zure harpidetzara gehituko da, etenik gabe.",
  "Con «Dar en el momento» das sellos, un uso de un bono o algo del momento sin que el cliente enseñe nada: él escanea tu QR.": "«Une horretan eman» aukerarekin zigiluak, bonu baten erabilera bat edo une horretako zerbait ematen duzu bezeroak ezer erakutsi gabe: berak eskaneatzen du zure QRa.",
