  "Correo o contraseña incorrectos.": "Helbidea edo pasahitza ez dira zuzenak.",
  "Crea la primera: «al décimo café, uno gratis». Puedes tener hasta {max}, cada una con lo suyo.": "Sortu lehenengoa: «hamargarren kafea, doan». Gehienez {max} izan ditzakezu, bakoitza bere arauekin.",
  "Crea una gratis": "Sortu bat doan",
  "Crea uno, por ejemplo «10 cafés por 12 €» o «5 clases por 40 €». Lo cobras tú en el local y Klendar lleva la cuenta de los usos.": "Sortu bat; adibidez, «10 kafe 12 €-tan» edo «5 eskola 40 €-tan». Zuk kobratzen duzu lokalean, eta Klendarrek erabileren kontua eramaten du.",
  "Crea uno: la gente participa gratis y, si quieres, añade tu negocio a favoritos.": "Sortu bat: jendeak doan hartzen du parte eta, nahi baduzu, zure negozioa gogokoetara gehitzen du.",
  "Creada": "Sortua",
