  "Croquetas de jamón": "Urdaiazpiko kroketak",
  "Crustáceos": "Krustazeoak",
  "Cualquiera": "Edozein",
  "Cualquiera de tu equipo marca desde Mi negocio, con un toque, cómo está el local: Hay sitio, Casi lleno o Lleno. Sale en tu ficha y en el mapa mientras estás abierto, y se quita solo a las 2 horas. Con el aforo en directo, se pone solo.": "Zure taldeko edonork markatzen du Nire negozioan, ukitu bakar batez, nola dagoen lokala: Badago lekua, Ia beteta edo Beteta. Zure fitxan eta mapan agertzen da irekita zauden bitartean, eta 2 orduren buruan kentzen da bere kabuz. Edukiera zuzenean erabiliz, bere kabuz jartzen da.",
  "Cuando alguien te pida presupuesto para un grupo, lo verás aquí.": "Norbaitek talde baterako aurrekontua eskatzen dizunean, hemen ikusiko duzu.",
  "Cuando el local está abierto": "Lokala irekita dagoenean",
  "Cuando hayas corregido lo que te dijimos, pídenos que lo miremos otra vez. Si quieres, cuéntanos qué has cambiado. Normalmente contestamos en 24–48 h.": "Esan genizuna zuzendu duzunean, eskatu berriro begiratzeko. Nahi baduzu, kontaiguzu zer aldatu duzun. Normalean 24–48 h-an erantzuten dugu.",
  "Cuando participes en uno, lo verás aquí con tu número.": "Batean parte hartzen duzunean, hemen ikusiko duzu zure zenbakiarekin.",
  "Cuando quien lleva el negocio cree un bono, lo verás aquí para venderlo.": "Negozioa daramanak bonu bat sortzen duenean, hemen ikusiko duzu saltzeko.",
  "Cuando quien lleva el negocio cree un sorteo, lo verás aquí.": "Negozioa kudeatzen duenak zozketa bat sortzen duenean, hemen ikusiko duzu.",
  "Cuando se acaban las plazas, la gente puede apuntarse. Si se libera una, avisamos por orden y cada persona tiene un rato para cogerla (30 minutos en una oferta flash, 2 horas en un evento).": "Plazak amaitzen direnean, jendeak izena eman dezake. Bat askatzen bada, ordenaren arabera abisatzen dugu, eta pertsona bakoitzak denbora tarte bat du hartzeko (30 minutu flash eskaintza batean, 2 ordu ekitaldi batean).",
  "Cuando tienen una fecha nueva cerca": "Zure inguruan data berri bat dutenean",
  "Cuando un bar cercano diga qué partidos pone, saldrán aquí.": "Inguruko taberna batek zer partida jartzen dituen esaten duenean, hemen agertuko dira.",
  "Cuando un negocio cerca organice uno, saldrá aquí.": "Inguruko negozio batek bat antolatzen duenean, hemen agertuko da.",
  "Cuando valides códigos, aquí verás lo que te traen tus ofertas.": "Kodeak balidatzen dituzunean, hemen ikusiko duzu zure eskaintzek zer ekartzen dizuten.",
  "Cuando vendas un bono, lo verás aquí con quién lo vendió y cada uso.": "Bonu bat saltzen duzunean, hemen ikusiko duzu, nork saldu zuen eta erabilera bakoitza.",
  "Cuatro por folio, para recortar. Se imprimen o se guardan en PDF desde el navegador.": "Lau orriko, mozteko. Nabigatzailetik inprimatzen edo PDFn gordetzen dira.",
