  "Cuenta eliminada": "Kontua ezabatu da",
  "Cuenta en la puerta con +1 y −1, y «¿Hay sitio ahora?» se pone solo.": "Kontatu atean +1 eta −1 erabiliz, eta «Ba al dago lekurik orain?» bere kabuz jartzen da.",
  "Cuenta escaneos, no personas: no guardamos quién escanea.": "Eskaneatzeak zenbatzen ditu, ez pertsonak: ez dugu gordetzen nork eskaneatzen duen.",
