  "Cuéntanos sobre tu negocio: lo revisamos antes de hacerlo público (normalmente en 24-48 h). Mientras, ya puedes preparar publicaciones.": "Kontatu zure negozioari buruz: publiko egin aurretik berrikusten dugu (normalean 24-48 h-tan). Bitartean, argitalpenak prestatzen has zaitezke.",
  "Cóbralo en el local antes de cargarlo: Klendar no cobra nada. Si te equivocas, lo puedes deshacer durante 10 minutos.": "Kobratu lokalean kargatu aurretik: Klendarrek ez du ezer kobratzen. Oker bazaude, 10 minutuz desegin dezakezu.",
