  "De {from} al cierre ({until})": "{from} – itxiera ({until})",
  "Declaro que los datos son ciertos y que puedo representar a esta entidad.": "Adierazten dut datuak egiazkoak direla eta erakunde hau ordezka dezakedala.",
  "Degustación gratis": "Dastaketa doan",
  "Deja de pagarse con la suscripción desde hoy (Stripe ajusta la próxima factura). El local no se borra; su plan vuelve a como estaba antes de pagar.": "Gaurtik aurrera ez da harpidetzarekin ordaintzen (Stripe-k hurrengo faktura doituko du). Lokala ez da ezabatzen; bere plana ordaindu aurretik zegoen bezala geratzen da.",
  "Deja de salir para vender. Los que ya vendiste siguen valiendo hasta que se gasten o caduquen.": "Ez da gehiago agertuko saltzeko. Saldu dituzunek balio dute agortu edo iraungi arte.",
  "Deja de verse en la app y en la web. Los premios ya entregados se quedan en el historial.": "Ez da gehiago ikusiko aplikazioan ez webgunean. Emandako sariak historian geratzen dira.",
  "Dejar de seguir": "Utzi jarraitzeari",
  "Dejar el sorteo": "Utzi zozketa",
  "Dejaremos de revisarla y el documento se borrará. Podrás volver a pedirla cuando quieras.": "Berrikusteari utziko diogu eta dokumentua ezabatu egingo da. Nahi duzunean eska dezakezu berriro.",
  "Dejará de funcionar para siempre (también su QR). Lo que trajo se queda en sus cifras.": "Betiko utziko dio funtzionatzeari (baita haren QRak ere). Ekarri zuena haren zenbakietan geratzen da.",
  "Dejará de poder validar códigos y de ver el panel.": "Ezin izango ditu kodeak balidatu ezta panela ikusi ere.",
  "Dejará de publicarse sola. Lo que ya se publicó se queda como está.": "Ez da gehiago bere kabuz argitaratuko. Argitaratutakoa dagoen bezala geratzen da.",
  "Dejarás de ver este panel y de validar sus códigos. Avisaremos al propietario.": "Ez duzu gehiago panel hau ikusiko, ezta haren kodeak balidatuko ere. Jabeari abisatuko diogu.",
  "Dejarás de ver su panel y de validar sus códigos. Avisaremos al propietario. Para volver, tendrán que invitarte otra vez.": "Ez duzu gehiago haren panela ikusiko, ezta haren kodeak balidatuko ere. Jabeari abisatuko diogu. Itzultzeko, berriro gonbidatu beharko zaituzte.",
