  "Detalles (opcional)": "Xehetasunak (aukerakoa)",
  "Di dónde es: como no tienes local fijo, cada publicación lleva su sitio.": "Esan non den: lokal finkorik ez duzunez, argitalpen bakoitzak bere lekua du.",
  "Di si el 2x1 incluye bebidas alcohólicas.": "Esan 2x1ak edari alkoholdunak barne hartzen dituen.",
  "Diagnóstico de piel gratis": "Azal-diagnostikoa doan",
  "Dinos qué pasa con esta petición. La revisará una persona del equipo de Klendar.": "Esan zer gertatzen den eskaera honekin. Klendarreko taldeko pertsona batek berrikusiko du.",
