  "Donde más te canjean es entre las {hora}:00 y las {hora2}:00.": "Truke gehien {hora}:00 eta {hora2}:00 artean egiten dizkizute.",
  "Dura": "Iraupena",
  "Durante": "Iraupena",
  "Durante 10 minutos puedes cargar o descontar sin volver a escanear. Cada venta y cada uso se pueden deshacer en ese rato.": "10 minutuz karga edo deskonta dezakezu berriro eskaneatu gabe. Salmenta eta erabilera bakoitza denbora tarte horretan desegin daiteke.",
  "Durante 24 horas puedes apuntar o corregir el importe del ticket de cada canje.": "24 orduz truke bakoitzaren tiketaren zenbatekoa idatzi edo zuzendu dezakezu.",
