  "Elige días entre hoy y dentro de un año.": "Aukeratu gaurtik urtebete barrura bitarteko egunak.",
  "Elige el día en que vuelves a abrir. Sin fecha, la pausa dura como mucho {max_days} días (hasta el {hasta}); puedes volver antes cuando quieras.": "Aukeratu berriro irekiko duzun eguna. Datarik gabe, pausak gehienez {max_days} egun irauten du ({hasta} arte); nahi duzunean itzul zaitezke lehenago.",
  "Elige hasta 3 negocios que acepten grupos y pídeles presupuesto a la vez.": "Aukeratu taldeak onartzen dituzten 3 negozio gehienez, eta eskatu aurrekontua guztiei batera.",
  "Elige hasta qué hora vale el código.": "Aukeratu noiz arte balio duen kodeak.",
  "Elige lo que eres: el alta cambia para pedirte solo lo que hace falta.": "Aukeratu zer zaren: altak behar dena bakarrik eskatuko dizu.",
