  "Es el enlace de un RRPP, no un código: pide al cliente su código.": "RRPP baten esteka da, ez kode bat: eskatu bezeroari bere kodea.",
  "Es el punto de tu ficha. Cada evento lleva luego su propio sitio.": "Zure fitxako puntua da. Gero, ekitaldi bakoitzak bere lekua izango du.",
  "Es el QR de «Dar en el momento»: lo escanea el cliente.": "«Une horretan eman» aukeraren QRa da: bezeroak eskaneatzen du.",
  "Es el QR del cartel del local: lo escanea el cliente.": "Lokaleko kartelaren QRa da: bezeroak eskaneatzen du.",
  "Es el único local de la suscripción: para dejar de pagar, cancela la suscripción.": "Harpidetzako lokal bakarra da: ordaintzeari uzteko, utzi harpidetza.",
  "Es en otro sitio": "Beste leku batean da",
  "Es festivo. Lo verá la gente en tu ficha; si no contestas, dirá «horario sin confirmar».": "Jaieguna da. Jendeak zure fitxan ikusiko du; erantzuten ez baduzu, «ordutegia berretsi gabe» jarriko du.",
  "Es hoy": "Gaur da",
  "Es lo que usa la app para decir a qué distancia estás. Arrastra la chincheta hasta la puerta y guarda.": "Aplikazioak hau erabiltzen du zer distantziatara zauden esateko. Arrastatu txintxeta atera arte eta gorde.",
  "Es lo único que se puede pedir: participar es gratis y sin compra.": "Hori da eska daitekeen gauza bakarra: parte hartzea doan da eta erosketarik gabe.",
  "Es mañana": "Bihar da",
  "Es para la próxima visita: todavía no vale.": "Hurrengo bisitarako da: oraindik ez du balio.",
  "Es solo para la primera visita y ya ha canjeado aquí.": "Lehen bisitarako da soilik, eta dagoeneko trukatu du hemen.",
  "Es tu propio QR: no puedes cargarte ni usar un bono a ti mismo.": "Zure QRa da: ezin duzu zeure buruari bonurik kargatu edo erabili.",
  "Es un QR de otro momento (una captura). Pide que abra Klendar.": "Beste une bateko QRa da (pantaila-argazki bat). Eskatu Klendar irekitzeko.",
  "Esa contraseña es muy fácil de adivinar. Usa al menos 8 caracteres y mezcla letras y números.": "Pasahitz hori errazegia da asmatzeko. Erabili gutxienez 8 karaktere, eta nahastu letrak eta zenbakiak.",
  "Esa cuenta está suspendida y no puede entrar en un equipo.": "Kontu hori etenda dago, eta ezin da talde batean sartu.",
  "Esa foto pesa demasiado. Prueba con otra más pequeña.": "Argazki hori handiegia da. Saiatu txikiago batekin.",
  "Esa foto pesa más de 5 MB.": "Argazki horrek 5 MB baino gehiago ditu.",
  "Esa oferta ya ha terminado. Puedes repetirla mañana.": "Eskaintza hori amaitu da jada. Bihar errepika dezakezu.",
  "Esa persona ya es RRPP de tu negocio.": "Pertsona hori dagoeneko zure negozioaren RRPP da.",
  "Esa persona ya está en el equipo. Su papel se cambia en la lista.": "Pertsona hori taldean dago jada. Haren rola zerrendan aldatzen da.",
  "Esa persona ya no es RRPP de tu negocio.": "Pertsona hori jada ez da zure negozioaren RRPP.",
