  "Esa pregunta ya no está.": "Galdera hori ez dago jada.",
  "Esa publicación ya estaba copiada en ese local.": "Argitalpen hori lokal horretan kopiatuta zegoen jada.",
  "Esa publicación ya no está activa.": "Argitalpen hori ez dago aktibo jada.",
  "Esa publicación ya no existe.": "Argitalpen hori ez dago jada.",
  "Esa serie ya ha terminado.": "Serie hori amaitu da.",
  "Esa tarjeta de sellos ya no está activa.": "Zigilu-txartel hori ez dago aktibo jada.",
  "Esas fechas ya han pasado.": "Data horiek iragan dira jada.",
  "Escanea el QR con la cámara (la del móvil o la del portátil) o escribe el código que la persona tiene debajo del QR. Cada código vale una vez: al validarlo queda marcado y el aforo baja.": "Eskaneatu QRa kamerarekin (mugikorrekoa edo ordenagailu eramangarrikoa) edo idatzi pertsonak QRaren azpian duen kodea. Kode bakoitzak behin balio du: balidatzean markatuta geratzen da eta edukiera jaisten da.",
