  "Escribe el importe en euros, por ejemplo 25 o 25,50.": "Idatzi zenbatekoa eurotan; adibidez, 25 edo 25,50.",
  "Escribe el motivo (de 5 a 200 caracteres): se lo diremos a quien participa.": "Idatzi arrazoia (5 eta 200 karaktere artean): parte hartzen dutenei esango diegu.",
