  "Escrita": "Idatzita",
  "Escrita, además, se puede buscar y la lee un lector de pantalla; si la escribes, es lo primero que se ve y los archivos y el enlace se quedan debajo. Si no te apetece, con una foto o un PDF vas servido.": "Idatzita, gainera, bilatu egin daiteke eta pantaila-irakurgailu batek irakurtzen du; idazten baduzu, hori ikusten da lehenik, eta fitxategiak eta esteka azpian geratzen dira. Gogorik ez baduzu, argazki batekin edo PDF batekin nahikoa da.",
