  "Estamos mirando el documento; normalmente tardamos 24–48 h. Hasta que lo verifiquemos no se puede publicar, pero ya puedes completar la ficha.": "Dokumentua aztertzen ari gara; normalean 24–48 h behar izaten ditugu. Egiaztatu arte ezin da argitaratu, baina fitxa osa dezakezu dagoeneko.",
  "Estamos revisando tu negocio; normalmente tardamos 24–48 h. Mientras tanto puedes preparar la ficha y tus publicaciones: se harán públicas al verificarlo. Si pasan más de 48 h sin noticias, escríbenos.": "Zure negozioa berrikusten ari gara; normalean 24–48 h behar izaten ditugu. Bitartean, fitxa eta argitalpenak presta ditzakezu: egiaztatzean argitaratuko dira. 48 h baino gehiago igarotzen badira berririk gabe, idatzi iezaguzu.",
