  "Has aceptado esta propuesta · le has compartido tu teléfono": "Proposamen hau onartu duzu · zure telefonoa partekatu duzu",
  "Has dejado el sorteo": "Zozketa utzi duzu",
  "Has dejado el sorteo.": "Zozketa utzi duzu.",
  "Has hecho demasiadas hoy. Prueba mañana.": "Gaur gehiegi egin dituzu. Saiatu bihar.",
  "Has llegado al límite de publicaciones activas de tu plan.": "Zure planaren argitalpen aktiboen mugara iritsi zara.",
  "Has llegado al límite de publicaciones activas de tu plan. Pausa alguna o cambia de plan.": "Zure planaren argitalpen aktiboen mugara iritsi zara. Pausatu baten bat edo aldatu plana.",
  "Has llegado al máximo de publicaciones activas de tu plan. Espera a que termine alguna o escríbenos.": "Zure planaren argitalpen aktiboen gehienezkora iritsi zara. Itxaron bat amaitu arte edo idatzi iezaguzu.",
  "Has salido del equipo de {nombre}": "{nombre} negozioaren taldetik irten zara",
  "Has terminado por hoy": "Gaurkoz amaitu duzu",
  "Has vendido {pasesTxt} por {currency} en tu local.": "{pasesTxt} saldu dituzu zure lokalean, guztira {currency}.",
  "Has vuelto a abrir": "Berriro ireki duzu",
  "Hasta": "Noiz arte",
  "Hasta 12 fotos: el local, el ambiente, lo que haces. Se ven en tu ficha.": "Gehienez 12 argazki: lokala, giroa, egiten duzuna. Zure fitxan ikusten dira.",
  "Hasta 6 fotos o vídeos. La primera es la portada; muévelas con las flechas. Si no pones ninguna, se usa la foto del local. Los vídeos se ven al abrir la publicación (en el feed van las fotos).": "Gehienez 6 argazki edo bideo. Lehenengoa azala da; mugitu geziekin. Bat ere jartzen ez baduzu, lokalaren argazkia erabiltzen da. Bideoak argitalpena irekitzean ikusten dira (jarioan argazkiak agertzen dira).",
  "Hasta cuándo": "Noiz arte",
  "Hasta cuántas personas": "Gehienez zenbat pertsona",
  "Hasta entonces sigue en prueba. Ese día se suma a la suscripción que ya pagas ({de}) y Stripe ajusta la próxima factura.": "Ordura arte proban jarraitzen du. Egun horretan dagoeneko ordaintzen duzun harpidetzara gehituko da ({de}) eta Stripek hurrengo faktura doituko du.",
  "Hasta entonces sigue en prueba. Ese día se suma a la suscripción que ya pagas y Stripe ajusta la próxima factura.": "Ordura arte proban jarraitzen du. Egun horretan dagoeneko ordaintzen duzun harpidetzara gehituko da eta Stripek hurrengo faktura doituko du.",
  "Hasta las {hora}": "{hora} arte",
  "Hasta que aceptes una propuesta, los negocios no ven quién eres.": "Proposamen bat onartu arte, negozioek ez dute ikusten nor zaren.",
  "Hasta un día": "Egun jakin bat arte",
  "Hasta una hora fija": "Ordu jakin bat arte",
  "hasta {asientos} plazas por código": "gehienez {asientos} plaza kodeko",
  "Hasta {MAX_ENLACES}.": "Gehienez {MAX_ENLACES}.",
  "Hasta {max} fotos.": "Gehienez {max} argazki.",
  "Hasta {n} personas": "Gehienez {n} pertsona",
  "hasta {porPersona} por persona": "gehienez {porPersona} pertsonako",
  "Hasta {s}": "{s} arte",
  "Hay 1 cambio más en el historial.": "Aldaketa 1 gehiago dago historian.",
  "Hay 1 reserva o código sin usar: sigue valiendo. Si no vas a atenderlo, cancela esa publicación.": "Erabili gabeko erreserba edo kode 1 dago: balio du oraindik. Ez baduzu artatuko, utzi argitalpen hori bertan behera.",
  "Hay alguien en el equipo menor de 18 años (o sin fecha de nacimiento en su perfil). Quítalo del equipo antes de marcar el negocio como +18.": "Taldean 18 urtetik beherako norbait dago (edo jaiotze-data profilean ez duen norbait). Kendu taldetik negozioa +18 gisa markatu aurretik.",
  "Hay cambios en esta publicación que todavía no has guardado.": "Argitalpen honetan oraindik gorde ez dituzun aldaketak daude.",
  "Hay cambios que todavía no has guardado.": "Oraindik gorde ez dituzun aldaketak daude.",
  "Hay cambios sin guardar.": "Gorde gabeko aldaketak daude.",
  "Hay dos con el mismo nombre.": "Bik izen bera dute.",
  "Hay gente con reserva": "Badago erreserba duen jendea",
  "Hay palabras que no podemos aceptar. Revisa lo que has escrito.": "Onartu ezin ditugun hitzak daude. Berrikusi idatzi duzuna.",
  "Hay que responder: varias comunidades prohíben el 2x1 en bebidas alcohólicas y la sanción es para el negocio. Si el 2x1 es de comida, refrescos o servicios, marca «No lleva alcohol».": "Erantzun egin behar da: hainbat erkidegok debekatzen dute 2x1 edari alkoholdunetan, eta isuna negozioarentzat da. 2x1a janarikoa, freskagarrietakoa edo zerbitzuetakoa bada, markatu «Ez du alkoholik».",
  "Hay sitio": "Badago lekua",
  "Hay un pago pendiente del plan.": "Planaren ordainketa bat dago zain.",
  "Hay un pago pendiente desde el {hold_since}. Tus publicaciones no se ven hasta que se resuelva; no se ha borrado nada.": "{hold_since}az geroztik ordainketa bat dago egiteke. Zure argitalpenak ez dira ikusiko konpondu arte; ez da ezer ezabatu.",
  "Hay un texto demasiado largo.": "Testu bat luzeegia da.",
  "Hay {codes} código sin usar de {antes}. Si lo dejas en {ahora}, esas personas pagarán {ahora} en el local. A quien ya canjeó no se le avisa.": "{antes} prezioko {codes} kode dago erabili gabe. Prezio berria {ahora} bada, pertsona horrek {ahora} ordainduko du lokalean. Dagoeneko trukatu duenari ez zaio abisatzen.",
  "Hay {codes} códigos sin usar de {antes}. Si lo dejas en {ahora}, esas personas pagarán {ahora} en el local. A quien ya canjeó no se le avisa.": "{antes} prezioko {codes} kode daude erabili gabe. Prezio berria {ahora} bada, pertsona horiek {ahora} ordainduko dute lokalean. Dagoeneko trukatu duenari ez zaio abisatzen.",
  "Hay {n} cambios más en el historial.": "{n} aldaketa gehiago daude historian.",
  "Hay {vivas} reservas o códigos sin usar: siguen valiendo. Si no vas a atenderlos, cancela esas publicaciones.": "Erabili gabeko {vivas} erreserba edo kode daude: balio dute oraindik. Ez badituzu artatuko, utzi argitalpen horiek bertan behera.",
  "Hazlo al cerrar. Al empezar otro día vuelve a 0 solo.": "Egin ezazu ixtean. Beste egun bat hastean bere kabuz itzultzen da 0ra.",
  "Hazlo solo si no puede enseñar su QR de cliente. Le llegará un aviso con los usos que le quedan.": "Egin ezazu bere bezero-QRa erakutsi ezin badu soilik. Abisu bat jasoko du, geratzen zaizkion erabilerekin.",
  "He olvidado la contraseña": "Pasahitza ahaztu dut",
  "Hecho": "Eginda",
  "Hecho. Ya sale en tu ficha.": "Eginda. Zure fitxan agertzen da jada.",
  "Hecho: tu negocio vuelve a estar en revisión": "Eginda: zure negozioa berriro dago berrikusten",
  "Hemos avisado de la nueva meta a 1 persona.": "Helburu berriaren berri eman diogu pertsona bati.",
  "Hemos avisado de la nueva meta a {notified} personas.": "Helburu berriaren berri eman diegu {notified} pertsonari.",
  "Hemos avisado de la nueva meta a {notified}.": "Helburu berriaren berri eman diegu: {notified}.",
  "Hemos añadido {x} a tus favoritos.": "Zure gogokoetara gehitu dugu: {x}.",
  "Hemos marcado tu negocio como cerrado.": "Zure negozioa itxita gisa markatu dugu.",
  "Herramientas": "Tresnak",
  "Herramientas opcionales para que la gente vuelva. Activa solo las que te encajen.": "Jendea itzul dadin aukerako tresnak. Aktibatu zuri egokitzen zaizkizunak bakarrik.",
  "Herramientas opcionales: activa las que te sirvan. Las que uses suben a la pantalla principal de tu negocio.": "Aukerako tresnak: aktibatu behar dituzunak. Erabiltzen dituzunak zure negozioaren pantaila nagusira igotzen dira.",
