  "horas desde que se apunta": "ordu izena ematen duenetik",
  "Hoy": "Gaur",
  "Hoy está en «Días cerrados»: mientras siga así, no se ve nada de tu local.": "Gaur «Itxitako egunak» atalean dago: horrela dagoen bitartean, ez da zure lokaleko ezer ikusten.",
  "Hoy no hay cola virtual.": "Gaur ez dago ilara birtualik.",
  "Hoy tu local sale cerrado en Klendar. ¿Abres hoy?": "Gaur zure lokala itxita ageri da Klendarren. Gaur irekitzen duzu?",
  "Hoy: ningún pedido avisado": "Gaur: ez da eskaerarik abisatu",
  "Hoy: {notified} pedido avisado": "Gaur: {notified} eskaera abisatuta",
