  "Invalid login credentials": "Helbidea edo pasahitza ez dira zuzenak.",
  "Invita al primero": "Gonbidatu lehena",
  "Invitaciones pendientes": "Zain dauden gonbidapenak",
  "Invitación cancelada": "Gonbidapena bertan behera utzi da",
  "Invitación enviada": "Gonbidapena bidali da",
  "Invitación enviada: entrará en el equipo cuando la acepte": "Gonbidapena bidali da: onartzen duenean sartuko da taldean",
  "Invitación enviada: le hemos mandado un correo": "Gonbidapena bidali da: mezu bat bidali diogu",
