  "nadie pierde los sellos que tiene": "inork ez ditu galtzen dituen zigiluak",
  "Nadie se ha apuntado aún esta noche. Cuando haya alguien, aquí lo buscas y le validas en la puerta.": "Oraindik ez du inork izena eman gaur gauean. Norbait dagoenean, hemen bilatu eta atean balidatuko duzu.",
  "Nadie se ha apuntado con sus enlaces en los últimos 30 días.": "Inork ez du izena eman haren esteken bidez azken 30 egunetan.",
  "Nadie verá tu ficha ni tus publicaciones en Descubre, el mapa o la búsqueda; quien tenga el enlace verá «Cerrado temporalmente». Lo abres de nuevo cuando quieras. Cerrar no cancela la suscripción.": "Inork ez ditu zure fitxa eta argitalpenak ikusiko Aurkitu atalean, mapan edo bilaketan; esteka duenak «Aldi baterako itxita» ikusiko du. Nahi duzunean ireki dezakezu berriro. Ixteak ez du harpidetza bertan behera uzten.",
