  "No habrá más fechas; las que ya están publicadas siguen en pie. Las {n} personas que la siguen recibirán un aviso.": "Ez da data gehiago egongo; argitaratuta daudenek aurrera jarraitzen dute. Jarraitzen duten {n} pertsonek abisua jasoko dute.",
  "No habrá más fechas; las que ya están publicadas siguen en pie.{n}": "Ez da data gehiago izango; dagoeneko argitaratutakoek aurrera jarraitzen dute.{n}",
