  "No hay partidos esta semana": "Ez dago partidarik aste honetan",
  "No hay pedidos esperando. Cuando alguien escanee el cartel, aparecerá aquí.": "Ez dago eskaerarik zain. Norbaitek kartela eskaneatzen duenean, hemen agertuko da.",
  "No hay publicaciones en este periodo.": "Ez dago argitalpenik aldi honetan.",
  "No hemos encontrado esa dirección en el mapa: arrastra la chincheta en «Ubicación en el mapa».": "Ez dugu helbide hori mapan aurkitu: arrastatu txintxeta «Kokapena mapan» atalean.",
  "No hemos encontrado un color en tu logo. Elígelo a mano.": "Ez dugu kolorerik aurkitu zure logoan. Aukeratu eskuz.",
  "No hemos podido cargar tu ficha.": "Ezin izan dugu zure fitxa kargatu.",
  "No hemos podido cobrar. Si no se resuelve antes del {bloqueoEl}, tu negocio quedará bloqueado (no se borra nada).": "Ezin izan dugu kobratu. {bloqueoEl} baino lehen konpontzen ez bada, zure negozioa blokeatuta geratuko da (ez da ezer ezabatzen).",
  "No hemos podido cobrar. Si no se resuelve antes del {grace_until}, pausaremos tus publicaciones (no se borra nada).": "Ezin izan dugu kobratu. {grace_until} baino lehen konpontzen ez bada, zure argitalpenak pausatuko ditugu (ez da ezer ezabatzen).",
  "No hemos podido completar el acceso. Vuelve a intentarlo.": "Ezin izan dugu sarbidea osatu. Saiatu berriro.",
  "No hemos podido comprobar que no eres un robot. Vuelve a probar.": "Ezin izan dugu egiaztatu robot bat ez zarela. Saiatu berriro.",
  "No hemos podido mandar el SMS. Revisa el número y vuelve a probar.": "Ezin izan dugu SMSa bidali. Egiaztatu zenbakia eta saiatu berriro.",
  "No hemos podido saber dónde estás. Revisa el permiso de ubicación del navegador.": "Ezin izan dugu jakin non zauden. Egiaztatu nabigatzailearen kokapen-baimena.",
  "No hemos podido terminar de entrar. Vuelve a intentarlo desde este navegador.": "Ezin izan dugu saioa hasten amaitu. Saiatu berriro nabigatzaile honetatik.",
  "No hemos podido verificar el negocio. Escríbenos a info@klendar.app.": "Ezin izan dugu negozioa egiaztatu. Idatzi iezaguzu info@klendar.app helbidera.",
  "No hemos podido verificar la entidad": "Ezin izan dugu erakundea egiaztatu",
