  "No puedes bajar el aforo a menos de {ocupadas}: ya hay {ocupadas} plazas reservadas o usadas.": "Ezin duzu edukiera {ocupadas} baino gutxiagora jaitsi: dagoeneko {ocupadas} plaza daude erreserbatuta edo erabilita.",
  "No puedes validar un código tuyo ni de tu equipo.": "Ezin duzu zure edo zure taldearen kode bat balidatu.",
  "No sale en Descubre, Explorar ni en tu ficha: solo la ve quien entra por el enlace o el QR de uno de tus RRPP.": "Ez da agertzen Aurkitu edo Arakatu ataletan, ezta zure fitxan ere: zure RRPPetako baten esteka edo QRaren bidez sartzen denak bakarrik ikusten du.",
  "No se cobra nada hasta que acabe tu prueba, el {period_end}. Sin permanencia: cancelas cuando quieras.": "Ez da ezer kobratzen zure proba amaitu arte, {period_end}. Iraupen-konpromisorik gabe: nahi duzunean utz dezakezu.",
  "No se cobra nada y los días que tenías pagados se guardan: se gastan al volver. Vuelve solo ese día, o antes si quieres, y avisamos a quien te tiene en favoritos.": "Ez da ezer kobratzen eta ordainduta zenituen egunak gordetzen dira: itzultzean erabiltzen dira. Egun horretan berez irekiko da, edo lehenago nahi baduzu, eta gogokoetan zaituztenei abisatuko diegu.",
  "No se ha podido abrir la cámara. Escribe el código a mano.": "Ezin izan da kamera ireki. Idatzi kodea eskuz.",
  "No se ha podido cargar. Prueba otra vez.": "Ezin izan da kargatu. Saiatu berriro.",
  "No se ha podido copiar": "Ezin izan da kopiatu",
  "No se ha podido descargar.": "Ezin izan da deskargatu.",
  "No se ha podido guardar": "Ezin izan da gorde",
  "No se ha podido guardar. Si vuelve a pasar, escríbenos a info@klendar.app.": "Ezin izan da gorde. Berriro gertatzen bada, idatzi iezaguzu info@klendar.app helbidera.",
  "No se ha podido hacer.": "Ezin izan da egin.",
  "No se ha podido. Vuelve a probar.": "Ezin izan da. Saiatu berriro.",
  "No se puede borrar mientras alguien tenga reserva: perdería su código sin enterarse. Si la cancelas, anulamos las reservas y avisamos a cada persona.": "Ezin da ezabatu norbaitek erreserba duen bitartean: bere kodea galduko luke jakin gabe. Bertan behera uzten baduzu, erreserbak ezeztatu eta pertsona bakoitzari abisatuko diogu.",
  "No se puede leer esta foto en este navegador: conviértela a JPG.": "Argazki hau ezin da nabigatzaile honetan irakurri: bihurtu JPG formatura.",
  "No se puede pausar con un pago por domiciliación en proceso.": "Ezin da pausatu helbideratutako ordainketa bat bidean dagoen bitartean.",
  "No se pueden sortear tabaco, vapeo ni apuestas.": "Ezin dira tabakoa, vapeoa edo apustuak zozketatu.",
  "No tengo local fijo (organizo eventos en distintos sitios)": "Ez dut lokal finkorik (hainbat lekutan antolatzen ditut ekitaldiak)",
