  "Opcional. Si no lo pones, la cocina va con el horario del local. Se usa en la ficha, en «Se puede comer ahora» y en el Menú del día.": "Aukerakoa. Jartzen ez baduzu, sukaldeak lokalaren ordutegia du. Fitxan, «Orain jan daiteke» atalean eta Eguneko menuan erabiltzen da.",
  "Opcional: lo puedes completar después desde Tu ficha.": "Aukerakoa: geroago osa dezakezu Zure fitxa ataletik.",
