  "Pega esta línea donde quieras que salga lo que tienes publicado. Se actualiza solo: no tienes que tocar nada más.": "Itsatsi lerro hau argitaratu duzuna agertzea nahi duzun lekuan. Bere kabuz eguneratzen da: ez duzu beste ezer ukitu behar.",
  "Pega esta línea en tu web y saldrá lo que tienes publicado. Se actualiza sola.": "Itsatsi lerro hau zure webgunean, eta argitaratuta duzuna agertuko da. Bere kabuz eguneratzen da.",
