  "Peticiones": "Eskaerak",
  "Petición enviada. Te avisamos cuando contesten (tienen 72 horas).": "Eskaera bidali da. Erantzuten dutenean abisatuko dizugu (72 ordu dituzte).",
  "Petición retirada": "Eskaera erretiratu da",
  "Pide a la persona su código (lo tiene en la app, debajo del QR) y escríbelo aquí. Cada código vale una vez: al validarlo queda marcado y el aforo baja. Si tienes cámara, desde la app es más rápido.": "Eskatu pertsonari bere kodea (aplikazioan du, QRaren azpian) eta idatzi hemen. Kode bakoitzak behin balio du: balidatzean markatuta geratzen da eta edukiera jaisten da. Kamera baduzu, aplikaziotik azkarragoa da.",
  "Pide {d}": "Eskatu {d}",
  "Pista a mitad de precio entre semana": "Pista erdi prezioan astegunetan",
