  "Plan en pausa": "Plana pausatuta",
  "Plan en pausa hasta el {paused_until}: no se cobra y tus publicaciones no se ven. Todo lo demás se queda como está.": "Plana pausatuta {paused_until} arte: ez da kobratzen eta zure argitalpenak ez dira ikusten. Gainerako guztia dagoen bezala geratzen da.",
  "Plan nuevo": "Plan berria",
