  "Plan {name}": "{name} plana",
  "Planes en los que se está a gusto sin compañía o se conoce gente: una cata en barra, un taller, un club de lectura.": "Lagunik gabe gustura egoteko edo jendea ezagutzeko planak: dastaketa bat barran, tailer bat, irakurle-talde bat.",
  "Planes para todas las edades que marques.": "Markatzen dituzun adin guztietarako planak.",
