  "Podrás mandar otro el {prox}": "Beste bat bidali ahal izango duzu data honetan: {prox}",
  "Podrás publicar cuando verifiquemos la entidad.": "Erakundea egiaztatzen dugunean argitaratu ahal izango duzu.",
  "Pon al menos el título antes de guardarla.": "Jarri gutxienez izenburua gorde aurretik.",
  "Pon el código «sin caducidad» para que valga como entrada.": "Jarri kodea «Iraungitzerik gabe», sarrera gisa balio dezan.",
  "Pon el nombre del negocio (dos letras como mínimo).": "Jarri negozioaren izena (gutxienez bi letra).",
  "Pon el nombre del negocio.": "Jarri negozioaren izena.",
  "Pon el precio anterior: la ley obliga a enseñarlo junto al descuento.": "Jarri aurreko prezioa: legeak deskontuarekin batera erakustera behartzen du.",
  "Pon el precio del menú (entre 1 y 200 €).": "Idatzi menuaren prezioa (1 eta 200 € artean).",
  "Pon tu logo y una foto": "Jarri zure logoa eta argazki bat",
  "Pon un aforo máximo entre 1 y 100.000 personas.": "Jarri 1 eta 100.000 pertsona arteko gehieneko edukiera.",
  "Pon un nombre de 2 a 60 caracteres.": "Idatzi 2 eta 60 karaktere arteko izena.",
  "Pon una hora de abrir y otra de cerrar distintas.": "Irekitzeko eta ixteko orduak ezberdinak izan behar dira.",
