  "Ponerlos todos": "Jarri guztiak",
  "Ponle un nombre (de 2 a 40 letras).": "Jarri izen bat (2 eta 40 letra artean).",
  "Ponle un nombre (dos letras como mínimo).": "Jarri izen bat (bi letra gutxienez).",
  "Ponle un nombre de 2 a 30 caracteres.": "Jarri 2 eta 30 karaktere arteko izen bat.",
  "Ponlo en el mostrador. Quien pide lo escanea y le avisamos cuando su pedido esté listo. Vale todos los días.": "Jarri mostradorean. Eskatzen duenak eskaneatzen du eta eskaera prest dagoenean abisatzen diogu. Egun guztietarako balio du.",
  "por": "egilea:",
  "Por ahora los sorteos no están disponibles en Klendar. Lo demás de Fidelizar funciona como siempre.": "Oraingoz zozketak ez daude erabilgarri Klendarren. Fidelizatu ataleko gainerakoak ohi bezala dabiltza.",
  "Por ahora no hay sorteos en Klendar. Mientras, mira lo que hay hoy cerca de ti.": "Oraingoz ez dago zozketarik Klendarren. Bitartean, begiratu gaur zer dagoen zure inguruan.",
  "Por ahora no tiene fechas": "Oraingoz ez du datarik",
  "por alguien del equipo": "taldeko norbaitek",
  "Por cada código validado sumamos el precio de la oferta por persona (el que tenía cuando la persona consiguió el código) por las plazas.": "Balidatutako kode bakoitzeko, eskaintzaren pertsonako prezioa (pertsonak kodea lortu zuenean zuena) bider plazak batzen ditugu.",
  "Por contestar": "Erantzuteko",
  "Por debajo del {n} %, «Hay sitio».": "% {n}etik behera, «Badago lekua».",
