  "Por ejemplo: Getafe": "Adibidez: Getafe",
  "Por ejemplo: getafe.es": "Adibidez: getafe.es",
  "Por ejemplo: Gracias por venir tanto este mes": "Adibidez: eskerrik asko hilabete honetan hainbeste etortzeagatik",
  "Por ejemplo: No acumulable con otras ofertas": "Adibidez: ezin da beste eskaintza batzuekin batu",
  "Por ejemplo: técnica de Cultura, presidente, secretaria": "Adibidez: Kulturako teknikaria, presidentea, idazkaria",
