  "Por ejemplo: Un postre gratis": "Adibidez: postre bat doan",
  "Por eso es un mínimo: lo que la gente gasta además, o en otras visitas, no lo vemos.": "Horregatik da gutxienekoa: jendeak gainera gastatzen duena, edo beste bisitetan, ez dugu ikusten.",
