  "Prueba con todo hasta el {fin}, sin tarjeta y sin renovación automática. Para seguir después, paga el plan; si no, tu negocio quedará bloqueado (no se borra nada).": "Proba dena barne {fin} arte, txartelik gabe eta berritze automatikorik gabe. Gero jarraitzeko, ordaindu plana; bestela, zure negozioa blokeatuta geratuko da (ez da ezer ezabatzen).",
