  "Quien escanee el cartel del local en tu negocio se lleva un sello, como mucho uno al día.": "Zure negozioan lokaleko kartela eskaneatzen duenak zigilu bat jasoko du, gehienez bat egunean.",
  "Quien la sigue recibirá un aviso cuando se publique.": "Jarraitzen dionak abisu bat jasoko du argitaratzen denean.",
  "Quien llega escanea el cartel de la puerta, coge número y le avisamos en el móvil cuando le toca. Tú solo tocas «Avisar al siguiente».": "Iristen denak atean dagoen kartela eskaneatzen du, txanda hartzen du, eta bere txanda iristen denean mugikorrean abisatzen diogu. Zuk «Abisatu hurrengoari» sakatu besterik ez duzu egin behar.",
  "Quien llega lo escanea con el móvil y coge número. Imprímelo y ponlo en la puerta.": "Iristen denak mugikorrarekin eskaneatzen du eta txanda hartzen du. Inprimatu eta jarri atean.",
  "Quien pide en el mostrador escanea el cartel y le avisamos en el móvil cuando su pedido está listo. Tú solo tocas «Listo».": "Mostradorean eskatzen duenak kartela eskaneatzen du eta eskaera prest dagoenean mugikorrean abisatzen diogu. Zuk «Prest» sakatu besterik ez duzu.",
  "Quien siga la serie recibirá un aviso con cada fecha nueva.": "Serieari jarraitzen dionak abisu bat jasoko du data berri bakoitzarekin.",
  "Quien te tenga en favoritos recibe una notificación (como mucho una al día por negocio, para no cansar).": "Gogokoetan zaituztenek jakinarazpen bat jasotzen dute (gehienez bat egunean negozio bakoitzeko, ez nekatzeko).",
  "Quien tiene código tiene sitio.": "Kodea duenak badu lekua.",
  "Quien tiene código tiene sitio. Para talleres, cenas o mesas. Si alguien no va y no anula, su plaza se queda sin usar.": "Kodea duenak lekua du. Tailer, afari edo mahaietarako. Norbait joaten ez bada eta bertan behera uzten ez badu, bere plaza erabili gabe geratzen da.",
