  "Se aplica ya a la persona que tiene sellos, y le avisamos.": "Zigiluak dituen pertsonari aplikatzen zaio dagoeneko, eta abisatuko diogu.",
  "Se aplica ya a las {n} personas que tienen sellos, y les avisamos.": "Zigiluak dituzten {n} pertsonei aplikatzen zaie dagoeneko, eta abisatuko diegu.",
