  "Sin conexión: lo mandamos en cuanto vuelva.": "Konexiorik gabe: itzultzen denean bidaliko dugu.",
  "Sin contestar": "Erantzun gabe",
  "Sin contestar a tiempo": "Garaiz erantzun gabe",
  "sin descripción": "deskribapenik gabe",
