  "Sin elegir ninguna: todas": "Bat ere aukeratu gabe: guztiak",
  "Sin fecha": "Datarik gabe",
  "Sin fechas a la vista": "Ez dago datarik ikusmiran",
  "Sin foto sale la portada de tu ficha.": "Argazkirik gabe, zure fitxaren azala agertzen da.",
  "Sin fotos se usa la portada de tu local.": "Argazkirik gabe, zure lokalaren azala erabiltzen da.",
  "Sin fotos se usa la portada de tu local. Añade una foto para que se vea mejor.": "Argazkirik gabe, zure lokalaren azala erabiltzen da. Gehitu argazki bat hobeto ikus dadin.",
  "Sin fotos todavía": "Oraindik ez dago argazkirik",
  "Sin guardar": "Gorde gabe",
  "Sin horario": "Ordutegirik gabe",
  "Sin indicar": "Adierazi gabe",
  "Sin local fijo no hay aforo que contar.": "Lokal finkorik gabe ez dago edukierarik kontatzeko.",
  "Sin límite": "Mugarik gabe",
  "Sin límite de personas por RRPP": "RRPP bakoitzeko pertsona-mugarik gabe",
  "sin límite de publicaciones activas": "argitalpen aktiboen mugarik gabe",
  "Sin marcar": "Markatu gabe",
  "Sin marcar: en tu ficha no sale nada.": "Markatu gabe: zure fitxan ez da ezer agertzen.",
  "Sin nombre": "Izenik gabe",
  "Sin partidos a la vista": "Ez dago partidarik ikusmiran",
  "Sin permanencia: cancelas cuando quieras.": "Iraunkortasunik gabe: nahi duzunean uzten duzu.",
  "Sin permanencia: cancelas cuando quieras. Precios sin IVA.": "Iraupen-konpromisorik gabe: nahi duzunean utz dezakezu. Prezioak BEZik gabe.",
  "Sin permiso para la cámara. Actívalo en el candado de la barra de direcciones.": "Ez dago kamerarako baimenik. Aktibatu helbide-barrako giltzarrapotik.",
  "Sin peticiones ahora": "Orain ez dago eskaerarik",
  "Sin preparar": "Prestatu gabe",
  "Sin propuestas aún": "Oraindik proposamenik ez",
  "sin reserva": "erreserbarik gabe",
  "Sin respuesta": "Erantzunik gabe",
  "Sin teléfono, web ni redes": "Telefonorik, webik eta sarerik gabe",
  "Sin tope": "Mugarik gabe",
  "Sobria: panel liso y el color solo en el precio.": "Soila: panel laua, eta kolorea prezioan soilik.",
  "Soja": "Soja",
  "Solicitud enviada el {fecha}. Te avisamos cuando la revisemos.": "Eskaera bidalia: {fecha}. Berrikusten dugunean jakinaraziko dizugu.",
  "Solicitud enviada. Ahora completa la ficha: logo, portada y horarios.": "Eskaera bidali da. Orain osatu fitxa: logoa, azala eta ordutegiak.",
