  "Solo clientes con sellos en alguna de tus tarjetas": "Zure txarteletako batean zigiluak dituzten bezeroek bakarrik",
  "Solo con el enlace de un RRPP": "RRPP baten estekarekin soilik",
  "Solo cuenta como asistencia lo validado en la puerta. Lo que pagues a tus RRPP lo gestionas fuera de Klendar; tú eres responsable de tus RRPP.": "Atean balidatutakoa bakarrik hartzen da asistentziatzat. Zure RRPPei ordaintzen diezuna Klendarretik kanpo kudeatzen duzu; zu zara zure RRPPen arduraduna.",
  "Solo cuentan algunas categorías": "Kategoria batzuk bakarrik kontatzen dira",
