  "Solo cuentan los eventos": "Ekitaldiak bakarrik kontatzen dira",
  "Solo cuentan: {lista}": "Hauek bakarrik kontatzen dira: {lista}",
  "Solo el propietario del negocio puede pagar el plan.": "Negozioaren jabeak bakarrik ordain dezake plana.",
  "Solo el propietario o un encargado puede cambiarlo.": "Jabeak edo arduradun batek bakarrik alda dezake.",
