  "Solo el propietario o un encargado pueden enlazar teles.": "Jabeak edo arduradun batek bakarrik lot ditzake telebistak.",
  "Solo el propietario o un encargado pueden enviar mensajes.": "Jabeak edo arduradun batek bakarrik bidal ditzake mezuak.",
  "Solo el propietario puede abrirlo de nuevo.": "Jabeak bakarrik ireki dezake berriro.",
  "Solo el propietario puede dar de baja el negocio.": "Jabeak bakarrik eman diezaioke baja negozioari.",
  "Solo el propietario puede volver a abrirlo.": "Jabeak bakarrik ireki dezake berriro.",
  "Solo el propietario y los encargados pueden crear o editar publicaciones.": "Jabeak eta arduradunek bakarrik sor edo edita ditzakete argitalpenak.",
  "Solo enlaces de Spotify, YouTube, SoundCloud, Apple Music o Bandcamp.": "Spotify, YouTube, SoundCloud, Apple Music edo Bandcampeko estekak soilik.",
  "Solo eventos": "Ekitaldiek bakarrik",
  "Solo favoritos": "Gogokoentzat soilik",
  "Solo fotos (JPG, PNG, WebP o HEIC) y PDF.": "Argazkiak (JPG, PNG, WebP edo HEIC) eta PDFa soilik.",
  "Solo la podrá sacar quien no haya canjeado nunca nada en tu negocio. Tu equipo no cuenta.": "Zure negozioan inoiz ezer trukatu ez duenak bakarrik lortu ahal izango du. Zure taldea ez da kontuan hartzen.",
  "Solo la ve quien entra por el enlace o el QR de un RRPP.": "RRPP baten esteka edo QRaren bidez sartzen denak bakarrik ikusten du.",
  "Solo la ven ellos. Si a otra persona le llega el enlace, la ficha dice que es exclusiva y cómo conseguirla, sin enseñar el beneficio.": "Haiek bakarrik ikusten dute. Beste norbaiti esteka iristen bazaio, fitxak esklusiboa dela eta nola lortu esaten du, onura erakutsi gabe.",
  "Solo la verán mayores de 18. Comprueba que tu comunidad lo permite.": "18 urtetik gorakoek bakarrik ikusiko dute. Egiaztatu zure erkidegoak baimentzen duela.",
  "Solo lo que publican ayuntamientos, juntas de distrito, asociaciones y ONG, y la agenda municipal.": "Udalek, barrutiko batzordeek, elkarteek eta GKEek argitaratzen dutena eta udal-agenda soilik.",
  "Solo lo verá {x}. A los demás les diremos que has elegido otra.": "Hark bakarrik ikusiko du: {x}. Besteei beste bat aukeratu duzula esango diegu.",
  "Solo mayores de 18": "18 urtetik gorakoentzat soilik",
  "Solo ofertas flash": "Flash eskaintzek bakarrik",
  "Solo para mayores de 18": "18 urtetik gorakoentzat bakarrik",
  "Solo para mayores de 18 (todo lo que publiques quedará marcado y todo el equipo tiene que ser mayor de edad)": "18 urtetik gorakoentzat bakarrik (argitaratzen duzun guztia markatuta geratuko da, eta talde osoak adinez nagusia izan behar du)",
  "Solo para mayores de 18 (todo lo que publiques quedará marcado)": "18 urtetik gorakoentzat bakarrik (argitaratzen duzun guztia markatuta geratuko da)",
  "Solo para quien lo enseñe. Klendar no lo comprueba: lo mira tu equipo en la puerta (el escáner se lo recuerda).": "Erakusten duenarentzat soilik. Klendarrek ez du egiaztatzen: zure taldeak begiratzen du atean (eskanerrak gogorarazten dio).",
  "Solo para quien reserva. Su QR cambia cada 30 segundos (una captura no sirve) y en la puerta ves su nombre, su foto si la tiene y cuántas veces ha venido.": "Erreserbatzen duenarentzat bakarrik. Bere QRa 30 segundoz behin aldatzen da (pantaila-argazki batek ez du balio) eta atean bere izena, argazkia baldin badu eta zenbat aldiz etorri den ikusten duzu.",
  "Solo para quien viene por primera vez": "Lehen aldiz datorrenarentzat soilik",
  "Solo puedes incluir locales de los que eres propietario.": "Zurea diren lokalak bakarrik sar ditzakezu.",
  "Solo quien tiene tu negocio en favoritos": "Zure negozioa gogokoetan dutenek bakarrik",
  "Solo RRPP": "RRPPentzat soilik",
  "Solo se pueden poner sellos a quien ya ha canjeado algo en tu negocio.": "Zure negozioan zerbait trukatu dutenei bakarrik jar dakizkieke zigiluak.",
  "Solo si eliges «Una serie nueva».": "«Serie berri bat» aukeratzen baduzu bakarrik.",
  "Solo si es distinto de tu local.": "Zure lokalaren desberdina bada soilik.",
  "Solo si este plan es distinto de tu local (p. ej. un taller infantil o un concierto en el patio).": "Plan hau zure lokalaren desberdina bada soilik (adib., haurrentzako tailer bat edo kontzertu bat patioan).",
  "Solo tú": "Zu bakarrik",
  "Solo ves su nombre visible y cuántas veces han venido: nada de datos de contacto. El regalo les llega como un código.": "Haien izen publikoa eta zenbat aldiz etorri diren baino ez duzu ikusten: harremanetarako daturik ez. Oparia kode gisa iristen zaie.",
  "Somos una entidad": "Erakunde bat gara",
  "Son 6 cifras.": "6 digitu dira.",
  "son los catorce que obliga a declarar el Reglamento 1169/2011. Pon solo los que sepas seguro: aquí equivocarse no es una errata.": "1169/2011 Erregelamenduak adieraztera behartzen dituen hamalauak dira. Jarri ziur dakizkizunak bakarrik: hemen oker ibiltzea ez da akats tipografiko bat.",
  "Sonido": "Soinua",
  "Sorteas algo tuyo (una manicura, una cena para dos…) entre quien participe en la app o en klendar.app.": "Zurea den zerbait zozketatzen duzu (manikura bat, bi lagunentzako afari bat…) aplikazioan edo klendar.app-en parte hartzen dutenen artean.",
