  "Spam o publicidad engañosa": "Spama edo publizitate engainagarria",
  "Stripe lo suma hoy y ajusta la próxima factura con la parte proporcional. Pierde los {diasPrueba} días de prueba que le quedan.": "Stripek gaur gehituko du eta hurrengo faktura doituko du dagokion zatiarekin. Geratzen zaizkion {diasPrueba} proba-egunak galduko ditu.",
  "Stripe no ha podido hacerlo. Prueba otra vez en un momento.": "Stripe-k ezin izan du egin. Saiatu berriro une batean.",
  "Stripe sumará este local a tu suscripción y ajustará la próxima factura con la parte proporcional.": "Stripe-k lokal hau zure harpidetzara gehituko du eta hurrengo faktura dagokion zatiarekin doituko du.",
  "Su código sigue valiendo; les avisamos de que está en pausa.": "Haien kodeak balio du oraindik; pausatuta dagoela abisatuko diegu.",
