  "sí": "bai",
  "Sí puedes validar los códigos y bonos que ya tiene la gente: lo que ya diste se respeta (bonos vendidos, sellos, premios, códigos y sorteos abiertos).": "Jendeak dituen kodeak eta bonuak balida ditzakezu: emandakoa errespetatzen da (saldutako bonuak, zigiluak, sariak, kodeak eta zozketa irekiak).",
