  "Tamaño mesa: cuatro por folio, para recortar y poner en las mesas.": "Mahai-tamaina: lau orri bakoitzeko, mozteko eta mahaietan jartzeko.",
  "También por visita con el QR del local": "Lokaleko QRarekin egindako bisitagatik ere bai",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva, y la persona que la sigue recibirá un aviso.": "Hurrengo datak ere bertan behera uzten dira, erreserba dutenei abisatuta, eta jarraitzen duen pertsonak abisua jasoko du.",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva, y las {n} personas que la siguen recibirán un aviso.": "Hurrengo datak ere bertan behera uzten dira, erreserba dutenei abisatuta, eta jarraitzen duten {n} pertsonek abisua jasoko dute.",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva.": "Hurrengo datak ere bertan behera uzten dira, erreserba dutenei abisatuta.",
  "También se cancelan las próximas fechas, con aviso a quien tenga reserva{n}.": "Hurrengo datak ere bertan behera uzten dira, eta erreserba dutenei abisatzen zaie{n}.",
  "También se ha pedido a 1 negocio más": "Beste negozio bati ere eskatu zaio",
