  "Tiene canjes validados, así que no se borra: se archiva. Deja de verse, sigue contando en Cifras y puedes crear otra a partir de ella.": "Balidatutako trukeak ditu; beraz, ez da ezabatzen: artxibatu egiten da. Ez da gehiago ikusten, Zenbakiak atalean kontatzen jarraitzen du, eta hartatik abiatuta beste bat sor dezakezu.",
  "Tiene canjes validados, así que no se borra: se archiva. Deja de verse, sigue contando en el Informe y puedes crear otra a partir de ella.": "Balidatutako trukeak ditu; beraz, ez da ezabatzen: artxibatu egiten da. Ez da gehiago ikusten, Txostenean kontatzen jarraitzen du, eta haretik abiatuta beste bat sor dezakezu.",
  "tiene palabras que no se permiten": "onartzen ez diren hitzak ditu",
  "Tiene palabras que no se pueden publicar. Cámbialo y vuelve a enviarlo.": "Argitaratu ezin diren hitzak ditu. Aldatu eta bidali berriro.",
  "Tienes": "Epea:",
  "Tienes 200 RRPP e invitaciones, el máximo.": "200 RRPP eta gonbidapen dituzu, gehienezkoa.",
  "Tienes 5 peticiones abiertas: cierra alguna antes.": "5 eskaera dituzu irekita: itxi baten bat lehenago.",
  "Tienes 50 series abiertas: termina alguna antes de crear otra.": "50 serie dituzu irekita: amaitu baten bat beste bat sortu aurretik.",
  "Tienes pagado hasta el {paid_until}. Si tienes dudas sobre lo pagado, escríbenos antes.": "Ordainduta duzu data honetara arte: {paid_until}. Ordaindutakoari buruz zalantzarik baduzu, idatzi iezaguzu lehenago.",
  "Tienes que aceptar las condiciones para negocios.": "Negozioentzako baldintzak onartu behar dituzu.",
  "Tienes que entrar en tu cuenta.": "Saioa hasi behar duzu.",
  "Tipo": "Mota",
  "Tipo de entidad": "Erakunde mota",
  "Tipo de entidad *": "Erakunde mota *",
  "Toca un apartado para cambiarlo. Cada uno se guarda por separado.": "Sakatu atal bat aldatzeko. Bakoitza bere aldetik gordetzen da.",
  "Toca una para ver su detalle, de dónde llegan y cómo va frente a las de tu zona.": "Ukitu bat haren xehetasunak ikusteko: jendea nondik datorren eta zure inguruko besteen aldean nola doan.",
  "Toca una y cámbiala a tu gusto.": "Sakatu bat, eta aldatu zure gustura.",
  "Todas": "Guztiak",
  "Todas las publicaciones": "Argitalpen guztiek",
  "Todavía nadie ha tocado tus enlaces.": "Oraindik inork ez ditu zure estekak sakatu.",
  "Todavía nadie la ha visto. En cuanto lleguen visitas y canjes, los verás aquí día a día.": "Oraindik inork ez du ikusi. Bisitak eta trukeak iristen direnean, hemen ikusiko dituzu egunez egun.",
  "Todavía nadie tiene sellos en esta tarjeta. Caen solos al validar códigos, o ponlos tú con «Añadir a alguien».": "Oraindik inork ez du zigilurik txartel honetan. Kodeak balidatzean jartzen dira bere kabuz, edo jarri zuk «Gehitu norbait» aukerarekin.",
  "Todavía no está validado. Compruébalo y pulsa «Validar».": "Oraindik ez dago balidatuta. Egiaztatu eta sakatu «Balidatu».",
  "Todavía no has contado nada.": "Oraindik ez duzu ezer kontatu.",
  "Todavía no has enlazado ninguna tele.": "Oraindik ez duzu telebistarik lotu.",
  "Todavía no has escrito la carta.": "Oraindik ez duzu karta idatzi.",
  "Todavía no has guardado ninguna.": "Oraindik ez duzu bat ere gorde.",
  "Todavía no has guardado ninguna. Rellena una publicación y guárdala como plantilla: la próxima vez la lanzas en dos toques.": "Oraindik ez duzu bat ere gorde. Bete argitalpen bat eta gorde txantiloi gisa: hurrengoan, bi ukitutan argitaratuko duzu.",
  "Todavía no has publicado nada.": "Oraindik ez duzu ezer argitaratu.",
  "Todavía no has puesto ningún enlace.": "Oraindik ez duzu estekarik jarri.",
  "Todavía no has subido ningún archivo.": "Oraindik ez duzu fitxategirik igo.",
  "Todavía no has validado ningún código.": "Oraindik ez duzu koderik balidatu.",
  "Todavía no hay nadie apuntado.": "Oraindik ez da inor apuntatu.",
  "Todavía no hay nadie más que haya canjeado algo en tu negocio.": "Oraindik ez dago zure negozioan zerbait trukatu duen beste inor.",
  "Todavía no le has avisado.": "Oraindik ez diozu abisatu.",
  "Todavía no se ha validado ningún código en este periodo.": "Aldi honetan ez da oraindik koderik balidatu.",
  "Todavía no tienen cuenta en Klendar. Entran solas al crear su cuenta con ese correo.": "Oraindik ez dute Klendarren konturik. Helbide horrekin kontua sortzean bere kabuz sartuko dira.",
  "Todavía no tienes ninguna tarjeta": "Oraindik ez duzu txartelik",
  "Todavía no tienes ningún negocio": "Oraindik ez duzu negoziorik",
  "Todavía no tienes publicaciones. Publica alguna y vuelve, o elige otra opción.": "Oraindik ez duzu argitalpenik. Argitaratu batenbat eta itzuli, edo aukeratu beste aukera bat.",
  "Todavía no tienes reseñas. Llegan cuando la gente canjea y vuelve a contarlo.": "Oraindik ez duzu iritzirik. Jendeak trukatu eta kontatzera itzultzen denean iristen dira.",
  "Todavía son pocas personas ({people}) para enseñarlo sin señalar a nadie. A partir de cinco aparece aquí.": "Oraindik pertsona gutxiegi dira ({people}) inor seinalatu gabe erakusteko. Bostetik aurrera agertzen da hemen.",
  "Todo": "Dena",
  "Todo el mundo": "Denek",
  "Todo sigue igual hasta el {fin}; desde ese día no se renueva y no se te cobra nada más. Puedes deshacerlo antes.": "Dena berdin jarraituko du data honetara arte: {fin}; egun horretatik aurrera ez da berrituko eta ez zaizu ezer gehiago kobratuko. Lehenago desegin dezakezu.",
