  "Va un {delta} % mejor que tu media.": "Zure batez bestekoa baino % {delta} hobeto doa.",
  "Va un {delta} % por debajo de tu media.": "Zure batez bestekoa baino % {delta} beherago doa.",
  "Vacaciones": "Oporrak",
  "Vacaciones, festivos, obras. Esos días no se ve nada de tu negocio, como con «Cerrado por hoy», y tu ficha dice hasta cuándo cierras. Al acabar, todo vuelve a verse solo.": "Oporrak, jaiegunak, obrak. Egun horietan ez da zure negozioaren ezer ikusten, «Gaur itxita» aukerarekin bezala, eta zure fitxak noiz arte ixten duzun esaten du. Amaitzean, dena berriro ikusten da bere kabuz.",
  "Vacaciones, obras, un festivo… Esos días no se ve nada de tu negocio.": "Oporrak, obrak, jaiegun bat… Egun horietan ez da zure negozioaren ezer ikusten.",
  "Vacía: sin caducidad.": "Hutsik: iraungitzerik gabe.",
  "vacío = sin límite": "hutsik = mugarik gabe",
  "Vacío = sin límite": "Hutsik = mugarik gabe",
  "Vacío: el general ({general}).": "Hutsik: orokorra ({general}).",
  "Vacío: sin límite, como el resto.": "Hutsik: mugarik gabe, gainerakoak bezala.",
  "Vale desde el día siguiente al canje y se valida en «Validar códigos», como los demás. Uno por canje; tu equipo no los recibe. Si menciona alcohol, solo lo reciben mayores de edad.": "Trukearen biharamunetik aurrera balio du, eta «Balidatu kodeak» atalean balidatzen da, besteak bezala. Bat truke bakoitzeko; zure taldeak ez ditu jasotzen. Alkohola aipatzen badu, adin nagusikoek bakarrik jasotzen dute.",
  "Validado": "Balidatuta",
