  "Vas muy rápido. Espera un momento y vuelve a probar.": "Oso azkar zoaz. Itxaron pixka bat eta saiatu berriro.",
  "Vende bonos en tu local («10 cafés por 12 €», «5 clases por 40 €»):": "Saldu bonuak zure lokalean («10 kafe 12 €-tan», «5 klase 40 €-tan»):",
