  "«Casi lleno» va del 10 al 95 % y «Lleno», al menos 5 puntos más, hasta el 100 %.": "«Ia beteta» % 10etik % 95era doa, eta «Beteta», gutxienez 5 puntu gehiago, % 100era arte.",
  "«Gestionar el pago» abre Stripe: tarjeta, datos de la factura (nombre fiscal, NIF y dirección) y tus facturas.": "«Kudeatu ordainketa» botoiak Stripe irekitzen du: txartela, fakturaren datuak (izen fiskala, IFZ eta helbidea) eta zure fakturak.",
  "«También por visita con el QR del local»": "«Lokaleko QRarekin egindako bisitagatik ere bai»",
  "«Todos los días» apagado": "«Egunero» desaktibatuta",
  "«{reward}». Se gastan {meta} sellos y queda apuntado como entregado.": "«{reward}». {meta} zigilu gastatzen dira, eta emandako gisa erregistratzen da.",
  "«{reward}». Ya lo había pedido: su código queda canjeado.": "«{reward}». Eskatuta zuen jada: haren kodea trukatuta geratzen da.",
  "«{title}» se publicará sola los días y la hora que elijas, con su cuenta atrás y su aforo. Puedes pausarla cuando quieras.": "«{title}» bere kabuz argitaratuko da aukeratzen dituzun egun eta orduan, bere atzerako kontaketa eta edukierarekin. Nahi duzunean pausatu dezakezu.",
  "«{title}» se publicará sola una semana antes de cada fecha, a la misma hora, con su aforo y sus reservas. Puedes pausarla cuando quieras.": "«{title}» bere kabuz argitaratuko da data bakoitza baino aste bat lehenago, ordu berean, bere edukiera eta erreserbekin. Nahi duzunean pausatu dezakezu.",
  "«{title}» terminará a las {nueva}. Quien ya tenga su código lo podrá usar hasta entonces.": "«{title}» ordu honetan amaituko da: {nueva}. Kodea dagoeneko duenak ordura arte erabili ahal izango du.",
  "«{x}» no se puede usar como nombre. Si es el nombre real del artista, escríbenos a info@klendar.app.": "«{x}» ezin da izen gisa erabili. Artistaren benetako izena bada, idatzi info@klendar.app helbidera.",
  "«{x}» no vale como nombre: entre 2 y 60 caracteres, con letras o números.": "«{x}» ez da baliozko izena: 2 eta 60 karaktere artean, letrekin edo zenbakiekin.",
  "«» se publicará sola los días y la hora que elijas, con su cuenta atrás y su aforo. Puedes pausarla cuando quieras.": "«» bere kabuz argitaratuko da aukeratzen dituzun egun eta orduan, bere atzera-kontaketarekin eta edukierarekin. Nahi duzunean pausa dezakezu.",
  "«» se publicará sola una semana antes de cada fecha, a la misma hora, con su aforo y sus reservas. Puedes pausarla cuando quieras.": "«» bere kabuz argitaratuko da data bakoitza baino astebete lehenago, ordu berean, bere edukiera eta erreserbekin. Nahi duzunean pausa dezakezu.",
